import argparse
import json
import os
import sys

DEFAULT_PATH = os.path.expanduser('~/.todo.json')


def load(path):
    try:
        with open(path, encoding='utf-8') as f:
            return json.load(f)
    except FileNotFoundError:
        return []


def save(path, items):
    with open(path, 'w', encoding='utf-8') as f:
        json.dump(items, f, ensure_ascii=False, indent=2)


def main(argv=None):
    p = argparse.ArgumentParser(description='シンプルな TODO 管理')
    p.add_argument('--file', default=DEFAULT_PATH, help='保存先 (既定: ~/.todo.json)')
    sub = p.add_subparsers(dest='cmd')
    a = sub.add_parser('add', help='TODO を追加')
    a.add_argument('text', nargs='+')
    sub.add_parser('list', help='一覧を表示')
    d = sub.add_parser('done', help='番号を指定して完了（削除）')
    d.add_argument('number', type=int)
    args = p.parse_args(argv)

    items = load(args.file)
    if args.cmd == 'add':
        items.append(' '.join(args.text))
        save(args.file, items)
        print(f'追加しました: {items[-1]}')
    elif args.cmd == 'done':
        if not 1 <= args.number <= len(items):
            p.error(f'番号は 1〜{len(items)} で指定してください')
        print(f'完了: {items.pop(args.number - 1)}')
        save(args.file, items)
    else:
        if not items:
            print('TODO はありません。追加: python todo.py add <内容>')
        for i, t in enumerate(items, 1):
            print(f'{i}. {t}')


if __name__ == '__main__':
    main()

